package server

import (
	"context"
	"io"
	"sync"
)

// bodyReader wraps an underlying reader. It aborts in-flight reads when
// the abort context is cancelled (e.g. during server shutdown).
type bodyReader struct {
	mu      sync.Mutex
	src     io.ReadCloser
	closed  bool
	abortCh chan struct{} // closed when the server is shutting down
}

func newBodyReader(r io.ReadCloser, abortCh chan struct) *bodyReader {
	return &bodyReader{src: r, abortCh: abortCh}
}

func (b *bodyReader) Read(p []byte) (int, error) {
	b.mu.Lock()
	if b.closed {
		b.mu.Unlock()
		return 0, io.ErrClosedPipe
	}
	b.mu.Unlock()

	type result struct {
		n   int
		err error
	}
	ch := make(chan result, 1)
	go func() {
		n, err := b.src.Read(p)
		ch <- result{n, err}
	}()

	select {
	case r := <-ch:
		return r.n, r.err
	case <-b.abortCh:
		return 0, context.Canceled
	}
}

func (b *bodyReader) Close() error {
	b.mu.Lock()
	defer b.mu.Unlock()
	b.closed = true
	return b.src.Close()
}

package server

import (
	"context"
	"net/http"
	"sync"
)

// Server is a thin wrapper around net/http.Server with graceful shutdown.
// On Shutdown, all pending body reads are aborted immediately.
type Server struct {
	httpServer *http.Server
	wg         sync.WaitGroup
	abortCh    chan struct{} // closed on Shutdown
	abortOnce  sync.Once
}

func New(addr string, handler http.Handler) *Server {
	s := &Server{abortCh: make(chan struct{})}
	// Wrap the user handler so we can inject abortCh into each request's body.
	wrapped := http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		r.Body = newBodyReader(r.Body, s.abortCh)
		s.wg.Add(1)
		defer s.wg.Done()
		handler.ServeHTTP(w, r)
	})
	s.httpServer = &http.Server{Addr: addr, Handler: wrapped}
	return s
}

func (s *Server) ListenAndServe() error {
	return s.httpServer.ListenAndServe()
}

// Shutdown closes the abort channel (interrupting all pending body reads),
// then delegates to the standard graceful shutdown.
func (s *Server) Shutdown(ctx context.Context) error {
	s.abortOnce.Do(func() { close(s.abortCh) })
	err := s.httpServer.Shutdown(ctx)
	s.wg.Wait()
	return err
}

