func TestBodyAbortedOnShutdown(t *testing.T) {
	t.Parallel()
	blocked := make(chan struct{})
	done := make(chan error, 1)

	srv := New(":0", http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		close(blocked)
		_, err := io.ReadAll(r.Body)
		done <- err
	}))

	ln, _ := net.Listen("tcp", ":0")
	go srv.httpServer.Serve(ln) //nolint:errcheck

	// Send a request with a body that never finishes.
	pr, _ := io.Pipe()
	req, _ := http.NewRequest(http.MethodPost,
		"http://"+ln.Addr().String(), pr)
	go http.DefaultClient.Do(req) //nolint:errcheck

	<-blocked // wait until handler is inside Read
	ctx, cancel := context.WithTimeout(context.Background(), 2*time.Second)
	defer cancel()
	if err := srv.Shutdown(ctx); err != nil {
		t.Fatalf("Shutdown: %v", err)
	}

	select {
	case err := <-done:
		if err == nil {
			t.Fatal("expected Read to return an error after shutdown")
		}
	case <-time.After(3 * time.Second):
		t.Fatal("handler did not return after shutdown")
	}
}

